import sys, math, json
sys.path.insert(0, sys.argv[1])
from fit import rows

# Master-mix correction (Leila 2031-02-10): C5 enzyme at 1:250 -> rates x (250/500)
for r in rows:
    if r["cond"] == "C5":
        r["v"] *= 250 / 500

def sse_vm(S, V, K):
    return sum((v - K_*0 - V*s/(K+s))**2 for s, v in zip(S, V))

def fit_free(S, v):
    # For fixed Km, best Vmax is closed form; golden-section on log Km
    def best_V(K):
        f = [s/(K+s) for s in S]
        V = sum(a*b for a, b in zip(f, v)) / sum(a*a for a in f)
        return V, sum((b - V*a)**2 for a, b in zip(f, v))
    lo, hi = math.log(0.1), math.log(1e5)
    g = (math.sqrt(5)-1)/2
    for _ in range(300):
        a, b = hi - g*(hi-lo), lo + g*(hi-lo)
        if best_V(math.exp(a))[1] < best_V(math.exp(b))[1]: hi = b
        else: lo = a
    K = math.exp((lo+hi)/2)
    V, _ = best_V(K)
    return V, K

def fit_km_only(S, v, V):
    def sse(K): return sum((b - V*a/(K+a)*1.0)**2 for a, b in zip(S, v))
    lo, hi = math.log(0.1), math.log(1e5)
    g = (math.sqrt(5)-1)/2
    for _ in range(300):
        a, b = hi - g*(hi-lo), lo + g*(hi-lo)
        if sse(math.exp(a)) < sse(math.exp(b)): hi = b
        else: lo = a
    return math.exp((lo+hi)/2)

conds = {}
excluded = []
for r in rows:
    if r["excl"]:
        excluded.append((r["sid"], r["excl"]))
        continue
    conds.setdefault(r["cond"], []).append(r)

for c in sorted(conds):
    pts = conds[c]
    print(c, "n=", len(pts), "ids:", " ".join(p["sid"][3:] for p in sorted(pts, key=lambda p: p["sid"])))

print()
results = {}
for c in ["C1", "C3", "C5", "C6", "C7"]:
    pts = conds[c]
    V, K = fit_free([p["S"] for p in pts], [p["v"] for p in pts])
    results[c] = (V, K)
    print(f"{c}: Vmax={V:.4f} um/s  Km={K:.2f} uM")

# inhibitor conditions: Vmax shared with same pH/temp no-inhibitor condition
V7 = results["C7"][0]
V5 = results["C5"][0]
for c, V_shared in [("C2", V7), ("C4", V5)]:
    pts = conds[c]
    K = fit_km_only([p["S"] for p in pts], [p["v"] for p in pts], V_shared)
    results[c] = (V_shared, K)
    print(f"{c}: Vmax(shared)={V_shared:.4f} um/s  Km_app={K:.2f} uM  n={len(pts)}")

print()
print("excluded:")
for sid, why in sorted(excluded):
    print(sid, "-", why)

json.dump({c: results[c] for c in results}, open(sys.argv[2], "w"))

